:root {
  color-scheme: dark;
  --ink: #f3f4f6;
  --muted: #a6b0c2;
  --panel: #1d2739;
  --field: #121a29;
  --line: #35435a;
  --mint: #72f0c1;
  --blue: #89a9ff;
}

* { box-sizing: border-box; }

body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #111827;
  background-image: radial-gradient(#35435a 1px, transparent 1px);
  background-size: 22px 22px;
  color: var(--ink);
  font: 16px/1.5 system-ui, sans-serif;
}

.card {
  width: min(100%, 540px);
  padding: clamp(24px, 6vw, 42px);
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--panel);
  box-shadow: 0 24px 70px #080c1480;
}

.pixel-mark {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  margin-bottom: 22px;
  border: 2px solid var(--mint);
  color: var(--mint);
  font-size: 24px;
  font-weight: 800;
  box-shadow: 4px 4px 0 #72f0c133;
}

.eyebrow { margin: 0 0 6px; color: var(--mint); font-size: 13px; font-weight: 750; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(30px, 8vw, 42px); line-height: 1.15; letter-spacing: -.04em; }
.intro { margin: 12px 0 28px; color: var(--muted); }
label { display: block; margin-bottom: 8px; font-weight: 650; }

textarea, input {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--field);
  color: var(--ink);
  font: inherit;
}

textarea { min-height: 120px; padding: 14px; resize: vertical; }
textarea::placeholder { color: #77849a; }
textarea:focus, input:focus, button:focus-visible { outline: 3px solid var(--blue); outline-offset: 3px; }

.shift-row { display: flex; align-items: center; gap: 12px; margin: 20px 0 22px; }
.shift-row label { margin: 0 auto 0 0; }
.shift-row input { width: 90px; padding: 9px 10px; text-align: center; }
.shift-hint { color: var(--muted); }
.actions { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 26px; }

button {
  min-height: 48px;
  padding: 10px 16px;
  border: 1px solid transparent;
  border-radius: 10px;
  font: inherit;
  font-weight: 750;
  cursor: pointer;
  transition: transform .12s ease, filter .12s ease, background .12s ease;
}
button:hover { filter: brightness(1.08); transform: translateY(-2px); }
button:active { transform: translateY(1px) scale(.98); }
.primary { background: var(--mint); color: #10251e; }
.secondary { border-color: var(--line); background: #27344a; color: var(--ink); }
.result-heading { display: flex; justify-content: space-between; align-items: baseline; }
.result-heading label { margin: 0 0 8px; }
#status { color: var(--mint); font-size: 14px; }
.result-box { min-height: 72px; padding: 14px; overflow-wrap: anywhere; white-space: pre-wrap; border: 1px dashed #52617a; border-radius: 10px; background: var(--field); color: var(--mint); }

@media (max-width: 400px) {
  body { padding: 18px 12px; }
  .card { border-radius: 15px; }
  .actions { gap: 8px; }
  button { padding-inline: 10px; }
}

const messageInput = document.getElementById('message');
const shiftInput = document.getElementById('shift');
const result = document.getElementById('result');
const status = document.getElementById('status');

function transform(direction) {
  const shift = Number(shiftInput.value);
  if (!Number.isInteger(shift) || shift < 1 || shift > 25) {
    shiftInput.setCustomValidity('Enter a whole number from 1 to 25.');
    shiftInput.reportValidity();
    shiftInput.focus();
    status.textContent = 'Check the shift amount.';
    return;
  }
  shiftInput.setCustomValidity('');
  const offset = direction === 'encode' ? shift : 26 - shift;
  result.textContent = Array.from(messageInput.value, (char) => {
    const code = char.charCodeAt(0);
    const base = code >= 65 && code <= 90 ? 65 : code >= 97 && code <= 122 ? 97 : 0;
    return base ? String.fromCharCode((code - base + offset) % 26 + base) : char;
  }).join('') || 'No message entered.';
  status.textContent = direction === 'encode' ? 'Encoded' : 'Decoded';
}

document.getElementById('encode').addEventListener('click', () => transform('encode'));
document.getElementById('decode').addEventListener('click', () => transform('decode'));
shiftInput.addEventListener('input', () => shiftInput.setCustomValidity(''));
